<script src="https://cdnjs.cloudflare.com/ajax/libs/html5-qrcode/2.3.8/html5-qrcode.min.js"></script>
<script>
let html5QrCode = null;
let scannerAktif = false;

function toggleScanner() {
    if (scannerAktif) {
        stopScanner();
        return;
    }
    document.getElementById('qrScannerWrap').classList.remove('hidden');
    html5QrCode = new Html5Qrcode('qrReader');
    scannerAktif = true;

    html5QrCode.start(
        { facingMode: 'environment' },
        { fps: 10, qrbox: { width: 220, height: 220 } },
        (decodedText) => {
            document.getElementById('keluarKode').value = decodedText.trim();
            document.getElementById('qrScannerStatus').textContent = 'QR terbaca: ' + decodedText.trim();
            stopScanner();
        },
        () => { /* frame tanpa QR terdeteksi, abaikan */ }
    ).catch((err) => {
        document.getElementById('qrScannerStatus').textContent = 'Tidak bisa mengakses kamera. Pastikan izin kamera diaktifkan.';
        scannerAktif = false;
    });
}

function stopScanner() {
    if (html5QrCode && scannerAktif) {
        html5QrCode.stop().then(() => {
            html5QrCode.clear();
            document.getElementById('qrScannerWrap').classList.add('hidden');
            scannerAktif = false;
        }).catch(() => {
            document.getElementById('qrScannerWrap').classList.add('hidden');
            scannerAktif = false;
        });
    } else {
        document.getElementById('qrScannerWrap').classList.add('hidden');
        scannerAktif = false;
    }
}

function toggleQris() {
    const dipilih = document.querySelector('input[name="metode_bayar"]:checked')?.value;
    document.getElementById('qrisWrap').classList.toggle('hidden', dipilih !== 'QRIS');
}
// Jalankan sekali saat halaman dimuat, untuk kasus default checked bukan Tunai
document.addEventListener('DOMContentLoaded', toggleQris);

async function submitKeluar(e) {
    e.preventDefault();
    const errBox = document.getElementById('keluarError');
    const sukBox = document.getElementById('keluarSukses');
    const btn = document.getElementById('keluarSubmitBtn');
    errBox.classList.add('hidden');
    sukBox.classList.add('hidden');

    const kodeParkir = document.getElementById('keluarKode').value.trim();
    const metodeBayar = document.querySelector('input[name="metode_bayar"]:checked')?.value;

    btn.disabled = true;
    btn.classList.add('opacity-60');

    try {
        const res = await fetch('transaksi.php', {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json', 'X-Requested-With': 'XMLHttpRequest' },
            body: JSON.stringify({ kode_parkir: kodeParkir, metode_bayar: metodeBayar })
        });
        const data = await res.json();
        if (data.success) {
            sukBox.textContent = 'Pembayaran berhasil diproses. Membuka struk untuk dicetak...';
            sukBox.classList.remove('hidden');
            window.open(data.struk_url, '_blank');
            setTimeout(() => window.location.reload(), 900);
        } else {
            errBox.textContent = data.message || 'Gagal mencatat kendaraan keluar.';
            errBox.classList.remove('hidden');
        }
    } catch (err) {
        errBox.textContent = 'Tidak dapat terhubung ke server.';
        errBox.classList.remove('hidden');
    }
    btn.disabled = false;
    btn.classList.remove('opacity-60');
    return false;
}
</script>

